CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read_own ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY profiles_insert_own ON public.profiles FOR INSERT TO authenticated WITH CHECK (id=auth.uid());
CREATE POLICY profiles_update_own ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE OR REPLACE FUNCTION public.create_player_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES (NEW.id,left(coalesce(NEW.raw_user_meta_data->>'display_name',NEW.raw_user_meta_data->>'name','Player'),100)) ON CONFLICT(id) DO NOTHING; RETURN NEW; END; $$;
CREATE TRIGGER create_player_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_player_profile();
INSERT INTO public.profiles(id,display_name) SELECT id,left(coalesce(raw_user_meta_data->>'display_name',raw_user_meta_data->>'name','Player'),100) FROM auth.users ON CONFLICT(id) DO NOTHING;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_read_own ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,text) TO authenticated,service_role;
CREATE TABLE public.player_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, team_number text NOT NULL REFERENCES public.registrations(team_number) ON DELETE CASCADE, game text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,game));
GRANT SELECT ON public.player_entries TO authenticated;
GRANT ALL ON public.player_entries TO service_role;
ALTER TABLE public.player_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY player_entries_read_own ON public.player_entries FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.register_player_entry(payload jsonb) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE code text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in to your player account first.'; END IF; IF EXISTS(SELECT 1 FROM public.player_entries WHERE user_id=auth.uid() AND game=payload->>'game') THEN RAISE EXCEPTION 'Your player account already has an entry for this game.'; END IF; code:=public.register_tournament_entry(payload); INSERT INTO public.player_entries(user_id,team_number,game) VALUES(auth.uid(),code,payload->>'game'); RETURN code; END; $$;
REVOKE ALL ON FUNCTION public.register_player_entry(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.register_player_entry(jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.claim_player_entry(code text,entry_password text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE found public.registrations; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first.'; END IF; SELECT * INTO found FROM public.registrations WHERE team_number=upper(trim(code)) AND password_hash=entry_password; IF found.id IS NULL THEN RAISE EXCEPTION 'Entry code or password is incorrect.'; END IF; INSERT INTO public.player_entries(user_id,team_number,game) VALUES(auth.uid(),found.team_number,found.game) ON CONFLICT(user_id,game) DO NOTHING; END; $$;
REVOKE ALL ON FUNCTION public.claim_player_entry(text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.claim_player_entry(text,text) TO authenticated;